//! The sillyecs world - generated from `ecs.yaml` by `build.rs` - and its systems:
//!
//! - `Traffic` steers the AI cars around each other and the player, and moves them.
//! - `TrafficIndex` buckets the cars into their track segments in the `Race` state.
//! - `Driving` applies the player's input, collisions and lap timing.
//!
//! All three run in order in the 60 Hz `FixedUpdate` phase.

// The included `*_gen.rs` is machine-generated by sillyecs and is not ours to lint.
#![allow(
    unsafe_code,
    unsafe_op_in_unsafe_fn,
    mismatched_lifetime_syntaxes,
    elided_lifetimes_in_paths,
    unused_qualifications,
    unreachable_patterns,
    dead_code
)]
#![allow(
    clippy::missing_safety_doc,
    clippy::new_without_default,
    clippy::nonminimal_bool,
    clippy::excessive_precision,
    clippy::len_without_is_empty,
    clippy::extra_unused_type_parameters,
    rustdoc::broken_intra_doc_links,
    rustdoc::redundant_explicit_links
)]

use std::convert::Infallible;

use game_toolkit::prelude::*;

use crate::race::*;
use crate::track::{SEGMENT_LENGTH, increase, overlap, percent_remaining, sprites};

// The generated world stores entity locations in a map type it expects to find by this name.
type EntityLocationMap<K, V> = std::collections::HashMap<K, V>;

include!(concat!(env!("OUT_DIR"), "/components_gen.rs"));
include!(concat!(env!("OUT_DIR"), "/archetypes_gen.rs"));
include!(concat!(env!("OUT_DIR"), "/systems_gen.rs"));
include!(concat!(env!("OUT_DIR"), "/world_gen.rs"));

/// The racer has no game-specific world commands.
type RacerCommand = WorldCommand<Infallible>;

pub type RacerWorld = MainWorld<NoOpPhaseEvents, ChannelQueue<RacerCommand>>;

// Implement the generated command-queue traits on the toolkit's mpsc-backed queue.
impl WorldUserCommand for ChannelQueue<RacerCommand> {
    type UserCommand = Infallible;
}
impl WorldCommandSender for ChannelQueue<RacerCommand> {
    type Error = std::sync::mpsc::SendError<RacerCommand>;
    fn send(&self, command: RacerCommand) -> Result<(), Self::Error> {
        ChannelQueue::send(self, command)
    }
}
impl WorldCommandReceiver for ChannelQueue<RacerCommand> {
    type Error = std::sync::mpsc::TryRecvError;
    fn recv(&self) -> Result<Option<RacerCommand>, Self::Error> {
        ChannelQueue::try_recv(self)
    }
}

impl WorldUserCommandHandler for RacerWorld {
    fn handle_user_command(&mut self, command: Infallible) {
        match command {}
    }
}

#[derive(Debug, Default)]
pub struct TrafficSystemData;
#[derive(Debug, Default)]
pub struct TrafficIndexSystemData;
#[derive(Debug, Default)]
pub struct DrivingSystemData;

/// Builds the (stateless) system instances for the world.
pub struct SystemFactory;

impl CreateSystem<TrafficSystem> for SystemFactory {
    fn create(&self) -> TrafficSystem {
        TrafficSystem::from(TrafficSystemData)
    }
}
impl CreateSystem<TrafficIndexSystem> for SystemFactory {
    fn create(&self) -> TrafficIndexSystem {
        TrafficIndexSystem::from(TrafficIndexSystemData)
    }
}
impl CreateSystem<DrivingSystem> for SystemFactory {
    fn create(&self) -> DrivingSystem {
        DrivingSystem::from(DrivingSystemData)
    }
}

impl ApplyTrafficSystem for TrafficSystem {
    type Error = Infallible;

    fn apply_many(
        &mut self,
        race: &RaceState,
        speeds: &[SpeedComponent],
        car_models: &[CarModelComponent],
        track_positions: &mut [TrackPositionComponent],
    ) {
        let track_length = race.track.length();
        let player_segment = race.track.find(race.player.position + player_z());
        for ((speed, model), pos) in speeds.iter().zip(car_models).zip(track_positions) {
            let speed = **speed;
            let car_segment = race.track.find(pos.z);
            pos.offset += steer_around(
                race,
                car_segment,
                player_segment,
                speed,
                pos.offset,
                model.w,
            );
            pos.z = increase(pos.z, STEP * speed, track_length);
            pos.percent = percent_remaining(pos.z, SEGMENT_LENGTH);
        }
    }
}

/// How far a car at `offset` swerves this step to get around slower cars (or the player) in
/// the next few segments, or to get back onto the road.
fn steer_around(
    race: &RaceState,
    car_segment: usize,
    player_segment: usize,
    speed: f32,
    offset: f32,
    sprite_w: f32,
) -> f32 {
    const LOOKAHEAD: usize = 20;

    // Don't bother steering around other cars when out of sight of the player.
    if car_segment as isize - player_segment as isize > DRAW_DISTANCE as isize {
        return 0.0;
    }

    let player = &race.player;
    let car_w = sprite_w * sprites::SCALE;
    let segments = race.track.len();
    for i in 1..LOOKAHEAD {
        let segment = (car_segment + i) % segments;

        // The closer the obstacle (smaller `i`) and the bigger the speed difference, the
        // harder the swerve.
        if segment == player_segment
            && speed > player.speed
            && overlap(player.x, PLAYER_W, offset, car_w, 1.2)
        {
            let dir = swerve_direction(offset, player.x);
            return dir / i as f32 * (speed - player.speed) / MAX_SPEED;
        }

        for other in &race.traffic[segment] {
            if speed > other.speed && overlap(offset, car_w, other.offset, other.width(), 1.2) {
                let dir = swerve_direction(offset, other.offset);
                return dir / i as f32 * (speed - other.speed) / MAX_SPEED;
            }
        }
    }

    // No cars ahead, but somehow ended up off road: steer back on.
    if offset < -0.9 {
        0.1
    } else if offset > 0.9 {
        -0.1
    } else {
        0.0
    }
}

/// Pass an obstacle on the inside when it is near an edge, else on whichever side we are.
fn swerve_direction(offset: f32, obstacle: f32) -> f32 {
    if obstacle > 0.5 {
        -1.0
    } else if obstacle < -0.5 || offset > obstacle {
        1.0
    } else {
        -1.0
    }
}

impl ApplyTrafficIndexSystem for TrafficIndexSystem {
    type Error = Infallible;

    fn on_begin_phase(&mut self, race: &mut RaceState) -> Result<(), Self::Error> {
        for cars in &mut race.traffic {
            cars.clear();
        }
        Ok(())
    }

    fn apply_many(
        &mut self,
        race: &mut RaceState,
        track_positions: &[TrackPositionComponent],
        speeds: &[SpeedComponent],
        car_models: &[CarModelComponent],
    ) {
        let cars = track_positions.iter().zip(speeds).zip(car_models);
        for ((pos, speed), model) in cars {
            let segment = race.track.find(pos.z);
            race.traffic[segment].push(TrafficCar {
                z: pos.z,
                offset: pos.offset,
                percent: pos.percent,
                speed: **speed,
                sprite: **model,
            });
        }
    }
}

impl ApplyDrivingSystem for DrivingSystem {
    type Error = Infallible;

    fn apply_single(
        &mut self,
        race: &mut RaceState,
        track_position: &mut TrackPositionComponent,
        speed: &mut SpeedComponent,
        driver: &mut DriverComponent,
    ) {
        drive(race, track_position, speed, driver);
    }
}

/// One step of the player's car: steering, speed, collisions, background scroll, lap times.
fn drive(
    race: &mut RaceState,
    pos: &mut TrackPositionData,
    speed: &mut f32,
    driver: &mut DriverData,
) {
    let dt = STEP;
    let player_z = player_z();
    let track_length = race.track.length();
    let segment = &race.track.segments[race.track.find(pos.z + player_z)];
    let input = race.input;
    let speed_percent = *speed / MAX_SPEED;
    // At top speed, crossing the road from left to right takes one second.
    let dx = dt * 2.0 * speed_percent;
    let start_position = pos.z;

    pos.z = increase(pos.z, dt * *speed, track_length);

    if input.left {
        pos.offset -= dx;
    } else if input.right {
        pos.offset += dx;
    }
    pos.offset -= dx * speed_percent * segment.curve * CENTRIFUGAL;

    *speed += dt
        * if input.faster {
            ACCEL
        } else if input.slower {
            BREAKING
        } else {
            DECEL
        };

    if pos.offset < -1.0 || pos.offset > 1.0 {
        if *speed > OFF_ROAD_LIMIT {
            *speed += dt * OFF_ROAD_DECEL;
        }
        for sprite in &segment.sprites {
            let sprite_w = sprite.source.w * sprites::SCALE;
            let side = if sprite.offset > 0.0 { 1.0 } else { -1.0 };
            let center = sprite.offset + sprite_w / 2.0 * side;
            if overlap(pos.offset, PLAYER_W, center, sprite_w, 1.0) {
                // Stop in front of the sprite, at the front of the segment.
                *speed = MAX_SPEED / 5.0;
                pos.z = increase(segment.p1[1], -player_z, track_length);
                break;
            }
        }
    }

    for car in &race.traffic[segment.index] {
        if *speed > car.speed && overlap(pos.offset, PLAYER_W, car.offset, car.width(), 0.8) {
            *speed = car.speed * (car.speed / *speed);
            pos.z = increase(car.z, -player_z, track_length);
            break;
        }
    }

    // Don't ever let the car go too far out of bounds, or exceed the top speed.
    pos.offset = pos.offset.clamp(-3.0, 3.0);
    *speed = speed.clamp(0.0, MAX_SPEED);

    let scroll = segment.curve * (pos.z - start_position) / SEGMENT_LENGTH;
    race.sky_offset = increase(race.sky_offset, SKY_SPEED * scroll, 1.0);
    race.hill_offset = increase(race.hill_offset, HILL_SPEED * scroll, 1.0);
    race.tree_offset = increase(race.tree_offset, TREE_SPEED * scroll, 1.0);

    let laps = &mut race.laps;
    if pos.z > player_z {
        if laps.current > 0.0 && start_position < player_z {
            laps.last_was_fastest = laps.current <= laps.fastest;
            if laps.last_was_fastest {
                laps.fastest = laps.current;
            }
            laps.last = Some(laps.current);
            laps.current = 0.0;
        } else {
            laps.current += dt;
        }
    }

    let steer = if input.left {
        -1.0
    } else if input.right {
        1.0
    } else {
        0.0
    };
    driver.steer = if *speed > 0.0 { steer } else { 0.0 };
    driver.updown = segment.p2[0] - segment.p1[0];

    race.player = PlayerSnapshot {
        position: pos.z,
        x: pos.offset,
        speed: *speed,
        steer: driver.steer,
        updown: driver.updown,
    };
}

/// Puts the player at the start line and scatters the AI cars around the track.
pub fn spawn_racers(world: &mut RacerWorld, rng: &mut Rng) {
    world.spawn_player_with(
        TrackPositionComponent::new(TrackPositionData::default()),
        SpeedComponent::new(0.0),
        DriverComponent::new(DriverData::default()),
    );

    let segments = world.states.race.track.len();
    for _ in 0..TOTAL_CARS {
        let offset = rng.next_f32() * 0.8 * crate::track::random_side(rng);
        let z = rng.range_usize(0..segments) as f32 * SEGMENT_LENGTH;
        let sprite = sprites::CARS[rng.range_usize(0..sprites::CARS.len())];
        let spread = if sprite == sprites::SEMI { 4.0 } else { 2.0 };
        let speed = MAX_SPEED / 4.0 + rng.next_f32() * MAX_SPEED / spread;
        world.spawn_car_with(
            TrackPositionComponent::new(TrackPositionData {
                z,
                offset,
                percent: 0.0,
            }),
            SpeedComponent::new(speed),
            CarModelComponent::new(sprite),
        );
    }
}
